import datetime as dt
from decimal import Decimal, InvalidOperation
from PIL import Image, ImageOps
import pytesseract
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
]

KEYWORD_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]

NUM_REGEX = re.compile(r'(\d{1,3}(?:,\d{3})+(?:\.\d{2})|\d+(?:\.\d{2})?)')

MONTH_MAP = {
    'JAN':1,'FEB':2,'MAR':3,'APR':4,'MAY':5,'JUN':6,
    'JUL':7,'AUG':8,'SEP':9,'SEPT':9,'OCT':10,'NOV':11,'DEC':12
}

DATE_PATTERNS = [
    re.compile(r'(\d{4})[\/.\-](\d{1,2})[\/.\-](\d{1,2})'),
    re.compile(r'(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})'),
]

MONTH_NAME_PATTERN = re.compile(r'(\d{1,2})\s*([A-Z]{3,4})\s*(\d{2,4})')


def preprocess_image(path: str):
    img = Image.open(path)
    img = ImageOps.exif_transpose(img)
    # upscale for better OCR
    scale = 2
    img = img.resize((img.width * scale, img.height * scale))
    img = img.convert('L')
    img = ImageOps.autocontrast(img)
    return img


def ocr_text(path: str) -> str:
    img = preprocess_image(path)
    text = pytesseract.image_to_string(img, config='--oem 3 --psm 6')
    return text or ''


def line_has_exclusion(upper_line: str) -> bool:
    return any(k in upper_line for k in EXCLUSION_KEYWORDS)


def extract_amount_from_line(line: str):
    matches = NUM_REGEX.findall(line)
    if not matches:
        return None
    raw = matches[-1]
    raw = raw.replace(',', '')
    try:
        val = Decimal(raw)
    except InvalidOperation:
        return None
    val = val.quantize(Decimal('0.00'))
    return f"{val:.2f}"


def extract_total(lines):
    for group in KEYWORD_GROUPS:
        for i, line in enumerate(lines):
            upper = line.upper()
            if line_has_exclusion(upper):
                continue
            if any(k in upper for k in group):
                amt = extract_amount_from_line(line)
                if amt:
                    return amt
                if i + 1 < len(lines):
                    next_line = lines[i + 1]
                    if not line_has_exclusion(next_line.upper()):
                        amt = extract_amount_from_line(next_line)
                        if amt:
                            return amt
    return None


def _make_date(y, m, d):
    if not (1 <= m <= 12 and 1 <= d <= 31):
        return None
    try:
        return dt.date(y, m, d)
    except ValueError:
        return None


def _normalize_year(y):
    if y < 100:
        return 2000 + y
    return y


def extract_date(lines):
    candidates = []
    for idx, line in enumerate(lines):
        upper = line.upper()
        has_date_kw = 'DATE' in upper

        # YYYY-MM-DD
        for m in DATE_PATTERNS[0].finditer(line):
            y, mo, d = map(int, m.groups())
            date_obj = _make_date(y, mo, d)
            if date_obj:
                score = 0
                if has_date_kw:
                    score += 3
                score += 2
                candidates.append((score, idx, date_obj))

        # DD/MM/YYYY or MM/DD/YYYY
        for m in DATE_PATTERNS[1].finditer(line):
            a, b, y = m.groups()
            a = int(a)
            b = int(b)
            y = _normalize_year(int(y))
            day = month = None
            if a > 12 and b <= 12:
                day, month = a, b
            elif b > 12 and a <= 12:
                month, day = a, b
            else:
                # default to DMY
                day, month = a, b
            date_obj = _make_date(y, month, day)
            if date_obj:
                score = 0
                if has_date_kw:
                    score += 3
                if int(m.groups()[2]) >= 100:
                    score += 2
                candidates.append((score, idx, date_obj))

        # Month name pattern e.g., 12 JAN 2024
        for m in MONTH_NAME_PATTERN.finditer(upper):
