            y = _normalize_year(int(y_s))
            date_obj = _make_date(y, mon, day)
            if date_obj:
                score = 0
                if has_date_kw:
                    score += 3
                if len(y_s) == 4:
                    score += 2
                candidates.append((score, idx, date_obj))

    if not candidates:
        return None
    # choose highest score, then earliest line
    candidates.sort(key=lambda x: (-x[0], x[1]))
    return candidates[0][2]


results = []
files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.tif', '.tiff', '.bmp'))])

for fname in files:
    path = os.path.join(IMG_DIR, fname)
    text = ocr_text(path)
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    total = extract_total(lines)
    date_obj = extract_date(lines)
    date_str = date_obj.isoformat() if date_obj else None
    results.append((fname, date_str, total))

wb = Workbook()
ws = wb.active
ws.title = 'results'
ws.append(['filename', 'date', 'total_amount'])
for row in results:
    ws.append(list(row))

wb.save(OUT_PATH)
print(f"Wrote {OUT_PATH} with {len(results)} rows")
