    except ValueError:
        return None


def _normalize_year(y):
    if y < 100:
        return 2000 + y
    return y


def extract_date(lines):
    candidates = []
    for idx, line in enumerate(lines):
        upper = line.upper()
        has_date_kw = 'DATE' in upper

        for m in DATE_PATTERNS[0].finditer(line):
            y, mo, d = map(int, m.groups())
            date_obj = _make_date(y, mo, d)
            if date_obj:
                score = 0
                if has_date_kw:
                    score += 3
                score += 2
                candidates.append((score, idx, date_obj))

        for m in DATE_PATTERNS[1].finditer(line):
            a, b, y = m.groups()
            a = int(a)
            b = int(b)
            y = _normalize_year(int(y))
            day = month = None
            if a > 12 and b <= 12:
                day, month = a, b
            elif b > 12 and a <= 12:
                month, day = a, b
            else:
                day, month = a, b
            date_obj = _make_date(y, month, day)
            if date_obj:
                score = 0
                if has_date_kw:
                    score += 3
                if len(m.groups()[2]) == 4:
                    score += 2
                candidates.append((score, idx, date_obj))

        for m in MONTH_NAME_PATTERN.finditer(upper):
            d_s, mon_s, y_s = m.groups()
            mon = MONTH_MAP.get(mon_s)
            if not mon:
                continue
            day = int(d_s)
            y = _normalize_year(int(y_s))
            date_obj = _make_date(y, mon, day)
            if date_obj:
                score = 0
                if has_date_kw:
                    score += 3
                if len(y_s) == 4:
                    score += 2
                candidates.append((score, idx, date_obj))

    if not candidates:
        return None
    candidates.sort(key=lambda x: (-x[0], x[1]))
    return candidates[0][2]


